import { createSlice, PayloadAction, Slice } from '@reduxjs/toolkit';
import {
  FilterRegistry,
  matchesTimePeriodPatch,
  migrateTimePeriodFilters,
  PerformanceToolFilterDataTransformer,
  recalculatePerformanceToolTimePeriod,
  resolvePerformanceToolKpiTimePeriodChange,
  resolvePerformanceToolTimePeriodTransition,
  supportsTimePeriodMigration,
  TimePeriodResolutionOutcome,
} from 'domain/Filter';
import type {
  FilterDataStructure,
  FilterForm,
  FilterPage,
  FiltersState,
  FilterValue,
  UpdateFormPayload,
  UpdateFormValuePayload,
} from 'models/Filters';
import { buildCommercialDrillDownClearPatch } from 'pages/pillars/ValueCreation/CommercialResults/commercialResultsClearDrillDown';
import { sanitizeCommercialCrossFilterForm } from 'pages/pillars/ValueCreation/CommercialResults/commercialResultsCrossFilterSanitize';
import {
  buildCommercialResultsPresetQueryParams,
  serializeCommercialPresetDriverSignature,
} from 'pages/pillars/ValueCreation/CommercialResults/commercialResultsFilterPreset';
import {
  autoSelectSingleSubBrandAfterPresetRefresh,
  reconcileCommercialBrandDependentDimensions,
  reconcileCommercialResultsForm,
} from 'pages/pillars/ValueCreation/CommercialResults/commercialResultsFilterReconciliation';
import { shouldSkipCommercialResultsFormCascade } from 'pages/pillars/ValueCreation/CommercialResults/commercialResultsFormCascade';
import {
  getCommercialPresetSkeletonFieldKeys,
  getCommercialPresetSkeletonFieldKeysForFlatDriverChange,
  normalizeCommercialPresetRefreshRequest,
  resolveCommercialResultsRefreshTier,
} from 'pages/pillars/ValueCreation/CommercialResults/commercialResultsRefreshMeta';
import { COMMERCIAL_RESULTS_PAGE_NAME } from 'pages/pillars/ValueCreation/CommercialResults/constants';
import { PERFORMANCE_TOOL_PAGE_NAME } from 'pages/pillars/ValueCreation/PerformanceTool/constants';

import { createInitialFilterPage } from './constants';
import {
  loadFilters,
  refreshCommercialResultsFilterData,
} from './thunk/filtersThunk';

const noPageFoundError = 'Filters: Page not found';

const IDLE_FILTER_PAGE = { status: 'idle' } as FilterPage;

const mergePartialFilterForm = (
  base: FilterForm,
  patch: Partial<FilterForm>,
): FilterForm => ({ ...base, ...patch }) as FilterForm;

const cloneFilterSnapshot = <T>(value: T): T =>
  JSON.parse(JSON.stringify(value)) as T;

function captureCommercialInitialPresetSnapshot(
  page: FilterPage,
  cached: boolean | undefined,
  dataFilters: FilterDataStructure | undefined,
): void {
  if (cached || !dataFilters) return;
  page.commercialInitialPresetSnapshot = {
    dataFilters: cloneFilterSnapshot(page.dataFilters),
    rawData: cloneFilterSnapshot(page.rawData),
    defaults: cloneFilterSnapshot(page.defaults),
    form: cloneFilterSnapshot(page.form),
  };
}

function syncCommercialFormPresetFromCommitted(page: FilterPage): void {
  page.commercialFormPresetDataFilters = cloneFilterSnapshot(page.dataFilters);
  page.commercialFormPresetRawData = cloneFilterSnapshot(page.rawData);
}

function commitCommercialFormPresetToApplied(page: FilterPage): void {
  if (!page.commercialFormPresetDataFilters) return;
  page.dataFilters = cloneFilterSnapshot(page.commercialFormPresetDataFilters);
  page.rawData = cloneFilterSnapshot(
    page.commercialFormPresetRawData ?? page.rawData,
  );
  page.lastCommercialRefreshTier = resolveCommercialResultsRefreshTier(
    page.applied,
  );
}

function getCommercialFormPreset(page: FilterPage): FilterDataStructure {
  return page.commercialFormPresetDataFilters ?? page.dataFilters ?? {};
}

function reconcileCommercialFormBeforeApply(page: FilterPage): FilterForm {
  const preset = getCommercialFormPreset(page);
  const sanitized = sanitizeCommercialCrossFilterForm(
    page.form,
    preset,
    page.defaults,
  );
  return reconcileCommercialResultsForm(preset, sanitized);
}

function reconcileCommercialQuickFiltersBeforeApply(
  page: FilterPage,
): FilterForm {
  const preset = getCommercialFormPreset(page);
  const sanitized = sanitizeCommercialCrossFilterForm(
    page.quickForm,
    preset,
    page.defaults,
  );
  return reconcileCommercialResultsForm(preset, sanitized);
}

function reconcileCommercialAppliedAfterDirectPatch(
  page: FilterPage,
  patch: Partial<FilterForm>,
): FilterForm {
  const preset = getCommercialFormPreset(page);
  const sanitized = sanitizeCommercialCrossFilterForm(
    mergePartialFilterForm(page.applied, patch),
    preset,
    page.defaults,
  );
  return reconcileCommercialResultsForm(preset, sanitized);
}

const isPerformanceToolData = (rawData: unknown): boolean =>
  !!rawData && PerformanceToolFilterDataTransformer.isValidFormat(rawData);

const resolveNavigatedKpi = (
  previousKpi: FilterValue | undefined,
  fallback: FilterValue | undefined,
): string => String(previousKpi || fallback || '').toLowerCase();

const normalizePreviousPageTimePeriod = (
  previousPage: FilterPage | undefined,
  targetFilterData: FilterDataStructure,
): FilterPage | undefined => {
  if (!previousPage || !supportsTimePeriodMigration(targetFilterData)) {
    return previousPage;
  }

  return {
    ...previousPage,
    applied: migrateTimePeriodFilters(previousPage.applied, targetFilterData),
  };
};

const resolvePageFilters = (
  currentPage: FilterPage | undefined,
  previousPage: FilterPage | undefined,
  page: FilterPage,
  isPerformanceTool: boolean,
) => {
  const normalizedPreviousPage = normalizePreviousPageTimePeriod(
    previousPage,
    page.dataFilters,
  );
  const resolved = FilterRegistry.resolveFilterCollisions(
    currentPage ?? IDLE_FILTER_PAGE,
    normalizedPreviousPage ?? IDLE_FILTER_PAGE,
    page.defaults,
  );

  if (!isPerformanceTool) {
    page.defaults = { ...resolved };
  }
  page.form = { ...resolved };
  page.applied = { ...resolved };
  page.quickForm = { ...resolved };
};

const computeDynamicDataFilters = (
  page: FilterPage,
  kpi: string,
  currentForm?: FilterForm,
) => {
  if (!isPerformanceToolData(page.rawData)) {
    return page.dataFilters || {};
  }
  return PerformanceToolFilterDataTransformer.transform(
    page.rawData,
    kpi,
    currentForm,
  );
};

const shouldPublishPerformanceToolFallback = (page: FilterPage): boolean => {
  const pendingSwitch = page.pendingPerformanceToolKpiSwitch;
  if (
    !pendingSwitch?.shouldShowFallback ||
    String(page.form.kpis ?? '') !== pendingSwitch.targetKpi
  ) {
    return false;
  }

  const targetFilterData = computeDynamicDataFilters(
    page,
    pendingSwitch.targetKpi,
    page.form,
  );
  const finalResolution = resolvePerformanceToolKpiTimePeriodChange(
    pendingSwitch.previousFilters,
    targetFilterData,
  );

  return (
    finalResolution.outcome === TimePeriodResolutionOutcome.DEFAULTED &&
    matchesTimePeriodPatch(page.form, finalResolution.patch)
  );
};

const hasTimePeriodOrKpiChange = (
  previous: FilterForm,
  next: FilterForm,
): boolean =>
  previous.kpis !== next.kpis ||
  previous.periods !== next.periods ||
  previous.period_type !== next.period_type ||
  previous.dt_end !== next.dt_end;

const patchesTimePeriodOrKpi = (patch: Partial<FilterForm>): boolean =>
  ['kpis', 'periods', 'period_type', 'dt_end'].some((key) => key in patch);

const isPerformanceToolPage = (pageName: string | null | undefined): boolean =>
  pageName === PERFORMANCE_TOOL_PAGE_NAME;

const clearPerformanceToolTransitionState = (page: FilterPage): void => {
  delete page.performanceToolTimePeriodFallback;
  delete page.pendingPerformanceToolKpiSwitch;
  delete page.performanceToolVolumeChartPeriodType;
};

const bumpPerformanceToolVolumeTimePeriodApplyToken = (
  page: FilterPage,
): void => {
  page.performanceToolVolumeTimePeriodApplyToken =
    (page.performanceToolVolumeTimePeriodApplyToken ?? 0) + 1;
};

const reconcilePerformanceToolFallbackAfterApply = (
  page: FilterPage,
  previousApplied: FilterForm,
): void => {
  const pendingSwitch = page.pendingPerformanceToolKpiSwitch;

  if (pendingSwitch) {
    if (shouldPublishPerformanceToolFallback(page)) {
      page.performanceToolTimePeriodFallback = {
        previousFilters: pendingSwitch.previousFilters,
        targetKpi: pendingSwitch.targetKpi,
      };
    } else {
      delete page.performanceToolTimePeriodFallback;
    }
    delete page.pendingPerformanceToolKpiSwitch;
    return;
  }

  if (
    page.performanceToolTimePeriodFallback &&
    hasTimePeriodOrKpiChange(previousApplied, page.form)
  ) {
    delete page.performanceToolTimePeriodFallback;
  }
};

type LoadFiltersFulfilledContext = {
  cached: boolean | undefined;
  dataFilters: FilterDataStructure | undefined;
  rawData: unknown;
  defaultKpi: string | undefined;
  isPerformanceTool: boolean;
  isRefresh: boolean;
};

function applyLoadFiltersFulfilledPageData(
  page: FilterPage,
  ctx: LoadFiltersFulfilledContext,
): void {
  const {
    cached,
    dataFilters,
    rawData,
    defaultKpi,
    isPerformanceTool,
    isRefresh,
  } = ctx;

  if (!cached && dataFilters) {
    page.rawData = rawData as FilterDataStructure;

    if (isPerformanceTool && !page.defaultKpi) {
      const initialKpi = resolveNavigatedKpi(
        defaultKpi ||
          (rawData as FilterDataStructure)?.kpis?.values?.[0]?.value,
        '',
      );
      page.dataFilters = PerformanceToolFilterDataTransformer.transform(
        rawData,
        initialKpi,
      );
    } else if (!isPerformanceTool) {
      page.dataFilters = dataFilters;
    }

    if (!isRefresh) {
      page.defaults = FilterRegistry.calculateDefaults(page.dataFilters);
    }
  }
}

function resolveLoadFiltersFulfilledForm(
  state: FiltersState,
  page: FilterPage,
  pageName: string,
  ctx: Pick<
    LoadFiltersFulfilledContext,
    'defaultKpi' | 'isPerformanceTool' | 'isRefresh'
  >,
): void {
  const { defaultKpi, isPerformanceTool, isRefresh } = ctx;
  if (isRefresh) return;

  if (isPerformanceTool) {
    const previousKpi = state.previousPage
      ? state.pages[state.previousPage]?.applied?.kpis
      : undefined;
    const navigatedKpi = resolveNavigatedKpi(
      defaultKpi || previousKpi,
      page.defaults?.kpis,
    );
    page.defaultKpi = navigatedKpi;
    page.defaults = { ...page.defaults, kpis: navigatedKpi };
  }

  resolvePageFilters(
    state.pages[pageName],
    state.previousPage ? state.pages[state.previousPage] : undefined,
    page,
    isPerformanceTool,
  );

  if (isPerformanceTool && page.defaultKpi) {
    page.form = { ...page.form, kpis: page.defaultKpi };
    page.quickForm = { ...page.quickForm, kpis: page.defaultKpi };
    page.applied = { ...page.applied, kpis: page.defaultKpi };
  }
}

const initialState: FiltersState = {
  pages: {},
  currentPage: null,
  previousPage: null,
};

type SwitchPerformanceToolKpiPayload = {
  targetKpi: string;
  applyImmediately?: boolean;
};

const _filterSlice = createSlice({
  name: 'filters',
  initialState,
  reducers: {
    setCurrentPage: (state, action: PayloadAction<string>) => {
      if (state.currentPage === action.payload) {
        return;
      }

      state.previousPage = state.currentPage;
      state.currentPage = action.payload;

      const newPage = state.pages[action.payload];
      const hasDefaults =
        newPage?.status === 'loaded' &&
        Object.keys(newPage.defaults).length > 0;

      if (!hasDefaults) return;

      const isPerformanceTool = isPerformanceToolData(newPage.rawData);

      if (isPerformanceTool) {
        clearPerformanceToolTransitionState(newPage);
        const urlKpi = new URLSearchParams(globalThis.location.search).get(
          'filter_kpis',
        );
        const previousKpi = state.previousPage
          ? state.pages[state.previousPage]?.applied?.kpis
          : undefined;
        const navigatedKpi = resolveNavigatedKpi(
          urlKpi || previousKpi,
          newPage.defaultKpi,
        );

        newPage.dataFilters = PerformanceToolFilterDataTransformer.transform(
          newPage.rawData,
          navigatedKpi,
        );
        newPage.defaultKpi = navigatedKpi;
        newPage.defaults = {
          ...FilterRegistry.calculateDefaults(newPage.dataFilters),
          kpis: navigatedKpi,
        };
      }

      resolvePageFilters(
        state.pages[action.payload],
        state.previousPage ? state.pages[state.previousPage] : undefined,
        newPage,
        isPerformanceTool,
      );

      if (isPerformanceTool && newPage.defaultKpi) {
        newPage.form = { ...newPage.form, kpis: newPage.defaultKpi };
        newPage.quickForm = { ...newPage.quickForm, kpis: newPage.defaultKpi };
        newPage.applied = { ...newPage.applied, kpis: newPage.defaultKpi };
      }
    },

    updateFormValue: (state, action: PayloadAction<UpdateFormValuePayload>) => {
      const { key, value } = action.payload;
      const currentPage = state.currentPage;

      if (!currentPage || !state.pages[currentPage]) {
        console.warn(noPageFoundError);
        return;
      }

      const page = state.pages[currentPage];
      const form = page.form;
      const kpi = key === 'kpis' ? String(value) : String(form?.kpis);
      const isPerformanceTool = isPerformanceToolData(page.rawData);
      const dataFilters = computeDynamicDataFilters(page, kpi, {
        ...form,
        [key]: value,
      });

      let nextForm: FilterForm;
      if (shouldSkipCommercialResultsFormCascade(currentPage, key)) {
        nextForm = { ...form, [key]: value };
      } else {
        nextForm = FilterRegistry.resolveCascadingUpdates(
          dataFilters,
          form,
          key,
          value,
        );
      }

      const timePeriodTransition =
        key === 'kpis' && isPerformanceTool
          ? resolvePerformanceToolTimePeriodTransition(form, dataFilters)
          : null;

      if (key === 'kpis' && isPerformanceTool) {
        clearPerformanceToolTransitionState(page);
      }

      page.form = timePeriodTransition
        ? { ...nextForm, ...timePeriodTransition }
        : nextForm;

      if (key === 'kpis') {
        page.dataFilters = dataFilters;
      }
    },
    switchPerformanceToolKpi: (
      state,
      action: PayloadAction<SwitchPerformanceToolKpiPayload>,
    ) => {
      const currentPage = state.currentPage;
      const page = currentPage ? state.pages[currentPage] : undefined;

      if (
        !isPerformanceToolPage(currentPage) ||
        !page ||
        !isPerformanceToolData(page.rawData)
      ) {
        return;
      }

      const { targetKpi, applyImmediately = false } = action.payload;
      const sourceForm = applyImmediately ? page.quickForm : page.form;
      const previousFilters = cloneFilterSnapshot(page.applied);
      const dataFilters = computeDynamicDataFilters(page, targetKpi, {
        ...sourceForm,
        kpis: targetKpi,
      });
      const nextForm = FilterRegistry.resolveCascadingUpdates(
        dataFilters,
        sourceForm,
        'kpis',
        targetKpi,
      );
      const resolution = resolvePerformanceToolKpiTimePeriodChange(
        previousFilters,
        dataFilters,
      );
      const resolvedForm = {
        ...nextForm,
        ...resolution.patch,
        kpis: targetKpi,
      };
      const pendingSwitch = {
        previousFilters,
        targetKpi,
        shouldShowFallback:
          resolution.outcome === TimePeriodResolutionOutcome.DEFAULTED,
      };

      page.dataFilters = dataFilters;
      page.form = resolvedForm;

      if (!applyImmediately) {
        page.pendingPerformanceToolKpiSwitch = pendingSwitch;
        return;
      }

      page.applied = { ...resolvedForm };
      page.quickForm = { ...resolvedForm };
      page.lastUpdated = Date.now();
      delete page.pendingPerformanceToolKpiSwitch;

      if (pendingSwitch.shouldShowFallback) {
        page.performanceToolTimePeriodFallback = {
          previousFilters,
          targetKpi,
        };
      } else {
        delete page.performanceToolTimePeriodFallback;
      }
    },

    dismissPerformanceToolTimePeriodFallback: (state) => {
      const currentPage = state.currentPage;
      if (!isPerformanceToolPage(currentPage)) return;

      const page = currentPage ? state.pages[currentPage] : undefined;
      if (page) delete page.performanceToolTimePeriodFallback;
    },

    setPerformanceToolVolumeChartPeriodType: (
      state,
      action: PayloadAction<{ periodType: string | null }>,
    ) => {
      const currentPage = state.currentPage;
      if (!isPerformanceToolPage(currentPage)) return;

      const page = currentPage ? state.pages[currentPage] : undefined;
      if (!page) return;

      if (action.payload.periodType) {
        page.performanceToolVolumeChartPeriodType = action.payload.periodType;
      } else {
        delete page.performanceToolVolumeChartPeriodType;
      }
    },

    returnToPreviousPerformanceToolKpi: (state) => {
      const currentPage = state.currentPage;
      const page = currentPage ? state.pages[currentPage] : undefined;
      const fallback = page?.performanceToolTimePeriodFallback;

      if (
        !isPerformanceToolPage(currentPage) ||
        !page ||
        !fallback ||
        !isPerformanceToolData(page.rawData)
      ) {
        return;
      }

      const previousFilters = cloneFilterSnapshot(fallback.previousFilters);
      const previousKpi = String(previousFilters.kpis ?? '');
      const dataFilters = computeDynamicDataFilters(
        page,
        previousKpi,
        previousFilters,
      );
      const timePeriodPatch = recalculatePerformanceToolTimePeriod(
        previousFilters,
        dataFilters,
      );
      const restoredFilters = {
        ...previousFilters,
        ...timePeriodPatch,
        kpis: previousKpi,
      };

      page.dataFilters = dataFilters;
      page.form = restoredFilters;
      page.applied = { ...restoredFilters };
      page.quickForm = { ...restoredFilters };
      page.lastUpdated = Date.now();
      clearPerformanceToolTransitionState(page);
    },
    updateQuickFiltersFormValue: (
      state,
      action: PayloadAction<UpdateFormValuePayload>,
    ) => {
      const { key, value } = action.payload;
      const currentPage = state.currentPage;

      if (!currentPage || !state.pages[currentPage]) {
        console.warn(noPageFoundError);
        return;
      }

      const page = state.pages[currentPage];
      const quickForm = page.quickForm;
      const kpi =
        key === 'kpis'
          ? String(value)
          : String(quickForm?.kpis ?? page.form?.kpis);
      const dataFilters = computeDynamicDataFilters(page, kpi, {
        ...quickForm,
        [key]: value,
      });

      if (shouldSkipCommercialResultsFormCascade(currentPage, key)) {
        page.quickForm = { ...quickForm, [key]: value };
      } else {
        page.quickForm = FilterRegistry.resolveCascadingUpdates(
          dataFilters,
          quickForm,
          key,
          value,
        );
      }

      if (key === 'kpis') {
        page.dataFilters = dataFilters;
      }
    },

    setFormDraft: (state, action: PayloadAction<FilterForm>) => {
      const currentPage = state.currentPage;

      if (!currentPage || !state.pages[currentPage]) {
        console.warn(noPageFoundError);
        return;
      }

      state.pages[currentPage].form = { ...action.payload };
    },

    resetAndApplyDefaults: (
      state,
      action: PayloadAction<UpdateFormPayload>,
    ) => {
      const { form, quickForm } = action.payload;
      const currentPage = state.currentPage;

      if (!currentPage) {
        return;
      }

      const page = state.pages[currentPage];

      if (!page) {
        return;
      }

      page.form = { ...form };
      page.quickForm = { ...quickForm };

      if (
        isPerformanceToolPage(currentPage) &&
        page.pendingPerformanceToolKpiSwitch
      ) {
        page.dataFilters = computeDynamicDataFilters(
          page,
          String(form.kpis ?? ''),
          form,
        );
        delete page.pendingPerformanceToolKpiSwitch;
      }

      if (currentPage === COMMERCIAL_RESULTS_PAGE_NAME) {
        syncCommercialFormPresetFromCommitted(page);
      }
    },

    applyFilters: (state) => {
      const currentPage = state.currentPage;

      if (!currentPage) {
        console.warn(noPageFoundError);
        return;
      }

      const page = state.pages[currentPage];

      if (!page) {
        console.warn(noPageFoundError);
        return;
      }

      if (currentPage === COMMERCIAL_RESULTS_PAGE_NAME) {
        page.form = reconcileCommercialFormBeforeApply(page);
      }

      const previousApplied = page.applied;
      page.applied = { ...page.form };
      if (isPerformanceToolPage(currentPage)) {
        reconcilePerformanceToolFallbackAfterApply(page, previousApplied);
      }
      page.quickForm = { ...page.applied };
      if (currentPage === COMMERCIAL_RESULTS_PAGE_NAME) {
        commitCommercialFormPresetToApplied(page);
      }
      page.lastUpdated = Date.now();
    },

    applyQuickFilters: (state) => {
      const currentPage = state.currentPage;

      if (!currentPage) {
        console.warn(noPageFoundError);
        return;
      }

      const page = state.pages[currentPage];

      if (!page) {
        console.warn(noPageFoundError);
        return;
      }

      if (currentPage === COMMERCIAL_RESULTS_PAGE_NAME) {
        page.quickForm = reconcileCommercialQuickFiltersBeforeApply(page);
      }

      const previousApplied = page.applied;
      page.applied = { ...page.quickForm };
      page.form = { ...page.applied };
      if (isPerformanceToolPage(currentPage)) {
        reconcilePerformanceToolFallbackAfterApply(page, previousApplied);
      }
      if (currentPage === COMMERCIAL_RESULTS_PAGE_NAME) {
        commitCommercialFormPresetToApplied(page);
      }
      page.lastUpdated = Date.now();
    },

    applyDirectValues: (state, action: PayloadAction<Partial<FilterForm>>) => {
      const currentPage = state.currentPage;

      if (!currentPage) {
        console.warn(noPageFoundError);
        return;
      }

      const page = state.pages[currentPage];

      if (!page) {
        console.warn(noPageFoundError);
        return;
      }

      page.form = mergePartialFilterForm(page.form, action.payload);
      page.quickForm = mergePartialFilterForm(page.quickForm, action.payload);

      if (currentPage === COMMERCIAL_RESULTS_PAGE_NAME) {
        page.form = reconcileCommercialFormBeforeApply(page);
        page.applied = reconcileCommercialAppliedAfterDirectPatch(
          page,
          action.payload,
        );
        commitCommercialFormPresetToApplied(page);
      } else {
        page.applied = mergePartialFilterForm(page.applied, action.payload);
      }

      if (
        isPerformanceToolPage(currentPage) &&
        patchesTimePeriodOrKpi(action.payload)
      ) {
        clearPerformanceToolTransitionState(page);
        if ('period_type' in action.payload || 'dt_end' in action.payload) {
          bumpPerformanceToolVolumeTimePeriodApplyToken(page);
        }
      }

      page.lastUpdated = Date.now();
    },

    resetToDefaults: (state) => {
      const currentPage = state.currentPage;

      if (!currentPage) {
        console.warn(noPageFoundError);
        return;
      }

      const page = state.pages[currentPage];

      if (!page) {
        console.warn(noPageFoundError);
        return;
      }

      page.form = { ...page.defaults };
      page.applied = { ...page.defaults };
      if (isPerformanceToolPage(currentPage)) {
        clearPerformanceToolTransitionState(page);
      }
      page.quickForm = { ...page.defaults };
      page.lastUpdated = Date.now();
    },

    bulkResetDraftFormFromDefaults: (
      state,
      action: PayloadAction<{ defaults: FilterForm }>,
    ) => {
      const currentPage = state.currentPage;

      if (!currentPage || !state.pages[currentPage]) {
        console.warn(noPageFoundError);
        return;
      }

      const page = state.pages[currentPage];
      const { defaults: defaultsPayload } = action.payload;

      const registry = FilterRegistry.getInstance();
      let form = { ...page.form };

      if (
        currentPage === COMMERCIAL_RESULTS_PAGE_NAME &&
        page.commercialInitialPresetSnapshot
      ) {
        const effectiveDefaults = { ...page.defaults, ...defaultsPayload };
        form = {
          ...form,
          ...buildCommercialDrillDownClearPatch(effectiveDefaults),
        };
      }

      for (const key of registry.getOrderedKeys()) {
        if (!(key in defaultsPayload)) continue;
        if (!registry.isResettable(key)) continue;
        const value = defaultsPayload[key];
        const kpi = key === 'kpis' ? String(value) : String(form?.kpis);
        const dataFilters = computeDynamicDataFilters(page, kpi, {
          ...form,
          [key]: value,
        });
        form = FilterRegistry.resolveCascadingUpdates(
          dataFilters,
          form,
          key,
          value,
        );
        if (key === 'kpis') {
          page.dataFilters = dataFilters;
        }
      }

      page.form = form;
      if (isPerformanceToolPage(currentPage)) {
        clearPerformanceToolTransitionState(page);
      }
    },

    bulkResetQuickFiltersFormFromDefaults: (
      state,
      action: PayloadAction<{ defaults: FilterForm }>,
    ) => {
      const currentPage = state.currentPage;

      if (!currentPage || !state.pages[currentPage]) {
        console.warn(noPageFoundError);
        return;
      }

      const page = state.pages[currentPage];
      const { defaults: defaultsPayload } = action.payload;

      const registry = FilterRegistry.getInstance();
      let quickForm = { ...page.quickForm };

      if (
        currentPage === COMMERCIAL_RESULTS_PAGE_NAME &&
        page.commercialInitialPresetSnapshot
      ) {
        const effectiveDefaults = { ...page.defaults, ...defaultsPayload };
        quickForm = {
          ...quickForm,
          ...buildCommercialDrillDownClearPatch(effectiveDefaults),
        };
      }

      for (const key of registry.getOrderedKeys()) {
        if (!(key in defaultsPayload)) continue;
        if (!registry.isResettable(key)) continue;
        const value = defaultsPayload[key];
        const kpi = key === 'kpis' ? String(value) : String(quickForm?.kpis);
        const dataFilters = computeDynamicDataFilters(page, kpi, {
          ...quickForm,
          [key]: value,
        });
        quickForm = FilterRegistry.resolveCascadingUpdates(
          dataFilters,
          quickForm,
          key,
          value,
        );
        if (key === 'kpis') {
          page.dataFilters = dataFilters;
        }
      }

      page.quickForm = quickForm;
    },

    mergePageDataFilters: (
      state,
      action: PayloadAction<{
        pageName: string;
        patch: Partial<FilterDataStructure>;
      }>,
    ) => {
      /**
       * Temporary mock-phase helper for Innovation Hub P&B local filter catalog.
       * Remove when INNOVATION_HUB_PB_MOCK_ONLY is false and BFF presets are complete.
       */
      const { pageName, patch } = action.payload;
      const page = state.pages[pageName];

      if (!page?.dataFilters) {
        return;
      }

      page.dataFilters = { ...page.dataFilters, ...patch };
      page.defaults = FilterRegistry.calculateDefaults(page.dataFilters);
    },

    setFilterVisibility: (
      state,
      action: PayloadAction<{ page: string; isHidden: boolean }>,
    ) => {
      const { page, isHidden } = action.payload;
      if (state.pages[page]) {
        state.pages[page].isHidden = isHidden;
      }
    },
  },

  extraReducers: (builder) => {
    builder
      .addCase(loadFilters.pending, (state, action) => {
        const { pageName } = action.meta.arg;

        if (!state.pages[pageName]) {
          state.pages[pageName] = createInitialFilterPage();
        }

        const page = state.pages[pageName];

        if (page.status === 'idle' || page.status === undefined) {
          page.status = 'loading';
        }

        if (pageName === COMMERCIAL_RESULTS_PAGE_NAME) {
          const targetTier = resolveCommercialResultsRefreshTier(page.form);
          page.commercialPresetRefresh = {
            pending: true,
            skeletonFieldKeys: getCommercialPresetSkeletonFieldKeys(
              targetTier,
              page.lastCommercialRefreshTier,
            ),
          };
        }
      })

      .addCase(loadFilters.fulfilled, (state, action) => {
        const { pageName, dataFilters, cached, rawData, defaultKpi } =
          action.payload;
        const page = state.pages[pageName];

        if (!page) return;

        if (!cached && !dataFilters) {
          page.status = 'error';
          return;
        }

        const isPerformanceTool = isPerformanceToolData(rawData);
        const isRefresh = isPerformanceTool && !!page.defaultKpi;
        const fulfilledCtx: LoadFiltersFulfilledContext = {
          cached,
          dataFilters,
          rawData,
          defaultKpi,
          isPerformanceTool,
          isRefresh,
        };

        applyLoadFiltersFulfilledPageData(page, fulfilledCtx);

        resolveLoadFiltersFulfilledForm(state, page, pageName, fulfilledCtx);

        page.status = 'loaded';

        if (pageName === COMMERCIAL_RESULTS_PAGE_NAME) {
          delete page.commercialPresetRefresh;
          captureCommercialInitialPresetSnapshot(page, cached, dataFilters);
          if (!cached && dataFilters) {
            syncCommercialFormPresetFromCommitted(page);
            page.lastCommercialRefreshTier =
              resolveCommercialResultsRefreshTier(page.applied ?? page.form);
            page.lastCommercialPresetDriverSignature =
              serializeCommercialPresetDriverSignature(
                page.applied ?? page.form,
              );

            const withAutoSubBrand = autoSelectSingleSubBrandAfterPresetRefresh(
              dataFilters,
              page.applied,
            );
            page.applied = withAutoSubBrand;
            page.form = { ...page.form, ...withAutoSubBrand };
            page.quickForm = {
              ...page.quickForm,
              ...withAutoSubBrand,
            };
          }
        }
      })

      .addCase(refreshCommercialResultsFilterData.pending, (state, action) => {
        const { scope, triggerField } = normalizeCommercialPresetRefreshRequest(
          action.meta.arg,
        );
        const page = state.pages[COMMERCIAL_RESULTS_PAGE_NAME];
        if (!page) return;

        if (scope === 'form') {
          page.latestCommercialFormRequestId = action.meta.requestId;
        } else {
          page.latestCommercialAppliedRequestId = action.meta.requestId;
        }

        if (scope !== 'form') return;
        const targetTier = resolveCommercialResultsRefreshTier(page.form);
        const nextDriverSignature = serializeCommercialPresetDriverSignature(
          page.form,
        );
        const tierSkeletons = getCommercialPresetSkeletonFieldKeys(
          targetTier,
          page.lastCommercialRefreshTier,
          triggerField,
        );
        const driverSkeletons =
          nextDriverSignature !== page.lastCommercialPresetDriverSignature
            ? getCommercialPresetSkeletonFieldKeysForFlatDriverChange(
                targetTier,
              )
            : [];
        page.commercialPresetRefresh = {
          pending: true,
          skeletonFieldKeys: [
            ...new Set([...tierSkeletons, ...driverSkeletons]),
          ],
        };
      })

      .addCase(
        refreshCommercialResultsFilterData.fulfilled,
        (state, action) => {
          const { pageName, dataFilters, rawData } = action.payload;
          if (pageName !== COMMERCIAL_RESULTS_PAGE_NAME) return;
          const page = state.pages[pageName];
          if (!page || !dataFilters) return;

          const scope = normalizeCommercialPresetRefreshRequest(
            action.meta.arg,
          ).scope;
          const latestRequestId =
            scope === 'applied'
              ? page.latestCommercialAppliedRequestId
              : page.latestCommercialFormRequestId;
          if (
            latestRequestId !== undefined &&
            action.meta.requestId !== latestRequestId
          ) {
            return;
          }
          const presetRaw = rawData ?? page.rawData;
          if (scope === 'applied') {
            page.rawData = presetRaw;
            page.dataFilters = dataFilters;
            page.commercialFormPresetDataFilters =
              cloneFilterSnapshot(dataFilters);
            page.commercialFormPresetRawData = cloneFilterSnapshot(presetRaw);
            page.lastCommercialRefreshTier =
              resolveCommercialResultsRefreshTier(page.applied ?? page.form);
            page.lastCommercialPresetDriverSignature =
              serializeCommercialPresetDriverSignature(
                page.applied ?? page.form,
              );

            const sanitizedApplied = sanitizeCommercialCrossFilterForm(
              page.applied,
              dataFilters,
              page.defaults,
            );
            const reconciled = reconcileCommercialBrandDependentDimensions(
              dataFilters,
              sanitizedApplied,
            );
            const withAutoSubBrand = autoSelectSingleSubBrandAfterPresetRefresh(
              dataFilters,
              reconciled,
            );
            page.applied = withAutoSubBrand;
            const formTier = resolveCommercialResultsRefreshTier(page.form);
            const appliedTier =
              resolveCommercialResultsRefreshTier(withAutoSubBrand);
            if (formTier === appliedTier) {
              page.form = { ...page.form, ...withAutoSubBrand };
            }
          } else {
            page.commercialFormPresetDataFilters = dataFilters;
            page.commercialFormPresetRawData = presetRaw;
            const sanitized = sanitizeCommercialCrossFilterForm(
              page.form,
              dataFilters,
              page.defaults,
            );
            page.form = reconcileCommercialBrandDependentDimensions(
              dataFilters,
              sanitized,
              page.applied,
            );

            const formParams = buildCommercialResultsPresetQueryParams(
              page.form,
            );
            const appliedParams = buildCommercialResultsPresetQueryParams(
              page.applied ?? page.form,
            );
            if (JSON.stringify(formParams) === JSON.stringify(appliedParams)) {
              commitCommercialFormPresetToApplied(page);
            }
          }

          delete page.commercialPresetRefresh;
        },
      )

      .addCase(refreshCommercialResultsFilterData.rejected, (state, action) => {
        const page = state.pages[COMMERCIAL_RESULTS_PAGE_NAME];
        if (!page) return;

        const scope = normalizeCommercialPresetRefreshRequest(
          action.meta.arg,
        ).scope;
        const latestRequestId =
          scope === 'applied'
            ? page.latestCommercialAppliedRequestId
            : page.latestCommercialFormRequestId;
        if (
          latestRequestId !== undefined &&
          action.meta.requestId !== latestRequestId
        ) {
          return;
        }

        delete page.commercialPresetRefresh;
      })

      .addCase(loadFilters.rejected, (state, action) => {
        const { pageName } = action.meta.arg;
        const page = state.pages[pageName];

        if (page) {
          page.status = 'error';
          delete page.commercialPresetRefresh;
        }
      });
  },
});

export const filterSlice: Slice<FiltersState> = _filterSlice;

export const {
  setCurrentPage,
  updateFormValue,
  switchPerformanceToolKpi,
  dismissPerformanceToolTimePeriodFallback,
  setPerformanceToolVolumeChartPeriodType,
  returnToPreviousPerformanceToolKpi,
  updateQuickFiltersFormValue,
  setFormDraft,
  resetAndApplyDefaults,
  applyFilters,
  applyQuickFilters,
  applyDirectValues,
  resetToDefaults,
  bulkResetDraftFormFromDefaults,
  bulkResetQuickFiltersFormFromDefaults,
  setFilterVisibility,
  mergePageDataFilters,
} = _filterSlice.actions;
